def matches(text):
    m = re_search(r"^From: (.+)$", text, MULTILINE)
    if m is None:
        return False
    name, addr = parseaddr(m.group(1))
    if addr.lower() != "billing@kestrelcloud.example":
        return False
    return all([
        re_search(r"^Invoice: INV-KCH-\d+$", text, MULTILINE) is not None,
        re_search(r"^Invoice date: ", text, MULTILINE) is not None,
        re_search(r"^Billing period: ", text, MULTILINE) is not None,
        re_search(r"^Total due: \$", text, MULTILINE) is not None,
    ])


def parse(text):
    parts = text.split("\n\n", 1)
    if len(parts) != 2:
        raise ValueError("no body")
    body = parts[1]
    vm = re_search(r"^(Kestrel Cloud Hosting, LLC)$", body, MULTILINE)
    if vm is None:
        raise ValueError("vendor line missing")
    vendor = vm.group(1)
    im = re_search(r"^Invoice: (INV-KCH-\d+)$", body, MULTILINE)
    if im is None:
        raise ValueError("invoice line missing")
    dm = re_search(r"^Invoice date: ([A-Za-z]+ \d{1,2}, \d{4})$", body, MULTILINE)
    if dm is None:
        raise ValueError("invoice date line missing")
    pm = re_search(r"^Billing period: ([A-Za-z]+ \d{1,2}, \d{4}) - ([A-Za-z]+ \d{1,2}, \d{4})$", body, MULTILINE)
    if pm is None:
        raise ValueError("billing period line missing")
    tm = re_search(r"^Total due: \$([\d,]+\.\d{2})$", body, MULTILINE)
    if tm is None:
        raise ValueError("total line missing")
    items = re_findall(r"^(.+?)\s{2,}\$([\d,]+\.\d{2})$", body, MULTILINE)
    if not items:
        raise ValueError("no line items")
    total = Decimal(tm.group(1).replace(",", ""))
    subtotal = Decimal("0")
    for desc, amt in items:
        subtotal += Decimal(amt.replace(",", ""))
    if subtotal != total:
        raise ValueError("line items do not sum to total")
    invoice_date = datetime.strptime(dm.group(1), "%B %d, %Y").date()
    start = datetime.strptime(pm.group(1), "%B %d, %Y").date()
    end = datetime.strptime(pm.group(2), "%B %d, %Y").date()
    if end < start:
        raise ValueError("billing period reversed")
    quotes = [
        im.group(0),
        dm.group(0),
        pm.group(0),
        tm.group(0),
    ]
    return {
        "contacts": [],
        "invoice_facts": [
            {
                "amount": float(tm.group(1).replace(",", "")),
                "billing_period": start.isoformat() + "/" + end.isoformat(),
                "invoice_date": invoice_date.isoformat(),
                "invoice_number": im.group(1),
                "quotes": quotes,
                "seats_billed": None,
            }
        ],
        "terms": [],
        "vendor_name": vendor,
    }
